describe('Login Page', () => {
  beforeEach(() => {
    cy.visit('/login')
  })

  it('should have a password show/hide toggle', () => {
    cy.get('[data-testid="password-toggle"]').should('be.visible')
    cy.get('[aria-label="Show password"]').should('be.visible')
    cy.get('[aria-label="Hide password"]').should('be.visible')
  })

  it('should toggle password visibility', () => {
    cy.get('[data-testid="password-input"]').type('password123')
    cy.get('[data-testid="password-toggle"]').click()
    cy.get('[data-testid="password-input"]').should('have.attr', 'type', 'text')
    cy.get('[data-testid="password-toggle"]').click()
    cy.get('[data-testid="password-input"]').should('have.attr', 'type', 'password')
  })
})

describe('Login Page', () => {
  beforeEach(() => {
    cy.visit('https://example.com/login') // replace with actual application URL
  })

  it('displays validation message for invalid credentials', () => {
    cy.get('[data-testid="username-input"]').type('invalid-username')
    cy.get('[data-testid="password-input"]').type('invalid-password')
    cy.get('[data-testid="login-button"]').click()

    cy.get('[data-testid="error-message"]').should('be.visible')
    cy.get('[data-testid="error-message"]').should('contain', 'Invalid username or password')
  })
})

describe('Login Page', () => {
  beforeEach(() => {
    cy.visit('/login')
  })

  it('should have a reachable forgot password link', () => {
    cy.get('[data-testid="forgot-password-link"]').should('be.visible')
    cy.get('[data-testid="forgot-password-link"]').should('be.enabled')
    cy.get('[data-testid="forgot-password-link"]').click().then(() => {
      cy.url().should('contain', '/forgot-password')
    })
  })

  it('should display forgot password link with aria-label', () => {
    cy.get('[aria-label="Forgot password"]').should('be.visible')
    cy.get('[aria-label="Forgot password"]').should('be.enabled')
    cy.get('[aria-label="Forgot password"]').click().then(() => {
      cy.url().should('contain', '/forgot-password')
    })
  })

  it('should display forgot password link with visible text', () => {
    cy.contains('Forgot password').should('be.visible')
    cy.contains('Forgot password').should('be.enabled')
    cy.contains('Forgot password').click().then(() => {
      cy.url().should('contain', '/forgot-password')
    })
  })
})
